          "consumer_service_id": {"type": "string", "description": "aip only: the row's consumer Service."},
          "evidence_refs": {"type": "array", "items": {"type": "string"}, "description": "aip only: evidence refs from that answer."},
          "note": {"type": "string"}
        }
      }
    }
  },
  "properties": {
    "q1": {
      "type": "object",
